pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address to1, address to2, uint v) public {
        vm.assume(from != address(0) && to1 != address(0) && to2 != address(0) && from != to1 && from != to2 && to1 != to2);
        vm.assume(v > 0 && v < 1e30);

        address token = address(0x1);
        address[] memory tos = new address[](2);
        tos[0] = to1;
        tos[1] = to2;

        uint beforeFrom = address(from).balance;
        uint beforeTo1 = address(to1).balance;
        uint beforeTo2 = address(to2).balance;

        (bool success, ) = address(c).call(abi.encodeWithSelector(c.transfer.selector, from, token, tos, v));

        uint afterFrom = address(from).balance;
        uint afterTo1 = address(to1).balance;
        uint afterTo2 = address(to2).balance;

        uint deltaFrom = beforeFrom - afterFrom;
        uint deltaTo1 = afterTo1 - beforeTo1;
        uint deltaTo2 = afterTo2 - beforeTo2;

        if (success) {
            assertTrue(deltaFrom == deltaTo1 + deltaTo2 && deltaTo1 == v && deltaTo2 == v);
        }
    }
}

