pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] memory _tos, uint256 v) public {
        // Bound the value to prevent overflow issues
        vm.assume(v < 1e30);
        vm.assume(_tos.length > 0);
        vm.assume(from != address(0) && caddress != address(0));
        // Record balances before transfer
        uint256[] memory beforeBalances = new uint256[](_tos.length);
        for (uint i = 0; i < _tos.length; i++) {
            vm.assume(_tos[i] != address(0));
            beforeBalances[i] = _tos[i].balance;
        }
        // Call transfer, if it reverts then skip assertion (revert is not a bug difference)
        (bool success, ) = address(c).call(abi.encodeWithSelector(
            bytes4(keccak256("transfer(address,address,address[],uint256)")),
            from, caddress, _tos, v
        ));
        if (!success) return;
        // The reference guarantees each recipient gained v, mutant gains 0
        for (uint i = 0; i < _tos.length; i++) {
            assertEq(_tos[i].balance, beforeBalances[i] + v);
        }
    }
}

