pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] memory _tos, uint v) public {
        // Precondition: from has enough ETH to cover the transfers (assuming token contract uses ETH)
        vm.assume(_tos.length > 0);
        vm.assume(v > 0);
        vm.assume(from != address(0) && caddress != address(0));
        for (uint i = 0; i < _tos.length; i++) {
            vm.assume(_tos[i] != address(0));
        }

        // Record initial balances of recipients
        uint256[] memory initialBalances = new uint256[](_tos.length);
        for (uint i = 0; i < _tos.length; i++) {
            initialBalances[i] = _tos[i].balance;
        }

        // Deal ETH to from for the transfer
        uint256 totalTransfer = v * _tos.length;
        vm.deal(from, totalTransfer);

        // Call transfer
        vm.prank(from);
        bool success = c.transfer(from, caddress, _tos, v);

        // Compute final balances sum
        uint256 sumFinal = 0;
        for (uint i = 0; i < _tos.length; i++) {
            sumFinal += _tos[i].balance;
        }
        uint256 sumInitial = 0;
        for (uint i = 0; i < _tos.length; i++) {
            sumInitial += initialBalances[i];
        }

        // The total balance of recipients should increase by v * number of recipients
        assertTrue(success && (sumFinal - sumInitial) == v * _tos.length);
    }
}

