pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] memory _tos, uint v) public {
        vm.assume(_tos.length > 0);
        vm.assume(from != address(this));
        uint256 initialBalance = from.balance;
        uint256 amount = v * _tos.length;
        vm.deal(from, initialBalance + amount);
        vm.prank(from);
        c.transfer(from, caddress, _tos, v);
        uint256 finalBalance = from.balance;
        assertTrue(finalBalance == initialBalance - amount);
    }
}
